        private static void BuildGuide()
        {
            System.IO.Directory.CreateDirectory("Assets/Game/Configs/Missions/Chapter03");var guide=AssetDatabase.LoadAssetAtPath<MissionFieldGuideConfig>(GuidePath);if(guide==null){guide=ScriptableObject.CreateInstance<MissionFieldGuideConfig>();AssetDatabase.CreateAsset(guide,GuidePath);}var basis=AssetDatabase.LoadAssetAtPath<MissionFieldGuideConfig>(M03RadarWarningGuideBuilder.Path);var classes=basis.Classes.ToArray();for(int i=0;i<classes.Length;i++)if(classes[i].Availability!=MissionGuideAvailability.Unavailable)classes[i].Availability=MissionGuideAvailability.Reference;guide.Configure(Enumerable.Range(1,5).Select(i=>new MissionGuideTopic{TitleKey=$"mission.safehouse_sweep.guide.{i}.title",BodyKey=$"mission.safehouse_sweep.guide.{i}.body",ExampleKey="mission.safehouse_sweep.guide.example",MistakeKey="mission.safehouse_sweep.guide.mistake",DiagramKey="mission.safehouse_sweep.guide.diagram"}).ToArray(),classes);EditorUtility.SetDirty(guide);
            GameObject root=PrefabUtility.LoadPrefabContents(M03RadarWarningUiBuilder.GuidePath);try{var data=new SerializedObject(root.GetComponentInChildren<MissionFieldGuideView>(true));data.FindProperty("safehouseSweepGuide").objectReferenceValue=guide;data.ApplyModifiedPropertiesWithoutUndo();MissionUiSerializedBindingsAuthoring.Apply(root);PrefabUtility.SaveAsPrefabAsset(root,M03RadarWarningUiBuilder.GuidePath);}finally{PrefabUtility.UnloadPrefabContents(root);}
        }

        private static void BindArt()
        {
            Texture art=CH03M02SafehouseSweepMediaImporter.Preview()??throw new InvalidOperationException("Safehouse Sweep art missing.");if(AssetDatabase.GetAssetPath(art)==CH03M02SafehouseSweepMediaImporter.SourceArt)throw new InvalidOperationException("Safehouse Sweep preview must not embed the full briefing UI mockup.");
            foreach(string path in new[]{"Assets/Game/Prefabs/UI/Shell/Content/SCN05_CampaignOperationsContent.prefab","Assets/Game/Prefabs/UI/Shell/Content/SCN06_MissionBriefingContent.prefab"}){GameObject root=PrefabUtility.LoadPrefabContents(path);try{var campaign=root.GetComponentInChildren<CampaignOperationsScreenView>(true);UnityEngine.Object view=campaign!=null?(UnityEngine.Object)campaign:root.GetComponentInChildren<MissionBriefingScreenView>(true);var data=new SerializedObject(view);var property=data.FindProperty(campaign!=null?"safehouseSweepMissionPreview":"safehouseSweepMissionArt");property.objectReferenceValue=art;data.ApplyModifiedPropertiesWithoutUndo();if(AssetDatabase.GetAssetPath(property.objectReferenceValue)!=CH03M02SafehouseSweepMediaImporter.PreviewPath)throw new InvalidOperationException("Safehouse Sweep clean preview binding failed: "+path);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
        }

